const wxClass = (w: string) => ({ 木: 'wx-wood', 火: 'wx-fire', 土: 'wx-earth', 金: 'wx-metal', 水: 'wx-water' } as Record<string, string>)[w] ?? '';
// 统一五行徽章：tag样式类
const wxTag = (w: string) => ({ 木: 'wood', 火: 'fire', 土: 'earth', 金: 'metal', 水: 'water' } as Record<string, string>)[w] ?? '';
// 统一关系标签样式：合红冲蓝刑橙害紫三合绿
const relTag = (r: string): { cls: string; name: string } => {
  if (r.includes('合') && r.includes('三')) return { cls: 'rel-sanhe', name: r };
  if (r.includes('合')) return { cls: 'rel-he', name: r };
  if (r.includes('冲')) return { cls: 'rel-chong', name: r };
  if (r.includes('刑')) return { cls: 'rel-xing', name: r };
  if (r.includes('害')) return { cls: 'rel-hai', name: r };
  return { cls: '', name: r };
};
// 统一吉凶等级徽章：上上/上/中/下/下下
const levelTag = (lv: string) => ({ 上上: 'shangshang', 上: 'shang', 中: 'zhongping', 下: 'xia', 下下: 'xiaxia' } as Record<string, string>)[lv] ?? '';

function InfoCard({ info, badges }: { info?: Array<{ label: string; value: React.ReactNode }>; badges?: React.ReactNode[] }) {
  if (!info?.length && !badges?.length) return null;
  return (
    <div className="row wrap" style={{ marginTop: 10 }}>
      {badges?.map((b, bi) => <span key={`b${bi}`} className="tag gold">{b}</span>)}
      {info?.map((i, ii) => <span key={`i${ii}-${i.label}`} className="tag"><b style={{ fontWeight: 600 }}>{i.label}</b>：{i.value}</span>)}
    </div>
  );
}

// ---------- 白话讲解弹窗（点击宫位元素后弹出） ----------
export interface PopupState {
  title: string;
  sections: Array<{ label: string; value: React.ReactNode; note?: React.ReactNode }>;
}
export function ExplainerPopup({ popup, onClose, actions }: { popup: PopupState | null; onClose: () => void; actions?: React.ReactNode }) {
  if (!popup) return null;
  return (
    <div className="modal-mask" onClick={onClose} role="dialog" aria-modal="true" aria-label="白话讲解">
      <div className="modal-panel qm-popup" onClick={e => e.stopPropagation()}>
        <div className="modal-head">
          <b>{popup.title}</b>
          <button className="btn sm" onClick={onClose} aria-label="关闭">×</button>
        </div>
        <div className="modal-body">
          {popup.sections.map((s, i) => (
            <div key={i} style={{ marginBottom: 10, padding: 8, background: 'var(--paper-2, rgba(47,72,88,.05))', borderRadius: 8 }}>
              <div className="small muted">{s.label}</div>
              <div style={{ fontSize: 14, fontWeight: 600, margin: '2px 0' }}>{s.value}</div>
              {s.note && <div className="small" style={{ color: 'var(--dai)' }}><span className="tag dai" style={{ marginRight: 4 }}>白话</span>{s.note}</div>}
            </div>
          ))}
        </div>
        {actions && <div className="modal-foot" style={{ padding: '4px 12px 10px', textAlign: 'right' }}>{actions}</div>}
      </div>
    </div>
  );
}

