// 我=宫五行，对方=星/门五行：同我=旺，生我=相，我生=休，我克=囚，克我=死
function qimenWangShuai(me: string, other: string | undefined): { lv: '旺' | '相' | '休' | '囚' | '死' | '—'; pct: number; color: string } {
  if (!other) return { lv: '—', pct: 50, color: '#9e9e9e' };
  const sheng: Record<string, string> = { 金: '水', 水: '木', 木: '火', 火: '土', 土: '金' };
  const ke: Record<string, string> = { 金: '木', 木: '土', 土: '水', 水: '火', 火: '金' };
  let lv: '旺' | '相' | '休' | '囚' | '死' = '旺'; let pct = 95;
  if (me === other) { lv = '旺'; pct = 95; }
  else if (sheng[other] === me) { lv = '相'; pct = 78; }      // 对方生我
  else if (sheng[me] === other) { lv = '休'; pct = 45; }      // 我生对方(泄气)
  else if (ke[me] === other) { lv = '囚'; pct = 30; }         // 我克对方(反耗)
  else if (ke[other] === me) { lv = '死'; pct = 15; }         // 对方克我
  else { lv = '休'; pct = 50; }
  const color = pct >= 85 ? '#2f9d5a' : pct >= 60 ? '#66bb6a' : pct >= 40 ? '#caa04d' : pct >= 25 ? '#ef6c00' : '#c0392b';
  return { lv, pct, color };
}
// 十二长生旺衰热力分（绿→红对应帝旺→绝）
function shengHeat(sheng: string | undefined): { pct: number; color: string } {
  if (!sheng) return { pct: 50, color: '#9e9e9e' };
  const table: Record<string, number> = { 长生: 62, 沐浴: 42, 冠带: 70, 临官: 86, 帝旺: 100, 衰: 38, 病: 28, 死: 12, 墓: 18, 绝: 5, 胎: 48, 养: 55 };
  const pct = table[sheng] ?? shengTableFallback(sheng);
  const color = pct >= 85 ? '#2f9d5a' : pct >= 60 ? '#66bb6a' : pct >= 40 ? '#caa04d' : pct >= 25 ? '#ef6c00' : '#c0392b';
  return { pct, color };
}
function shengTableFallback(s: string): number {
  // 两字简写：临=临官,帝=帝旺,沐=沐浴,冠=冠带,衰病墓绝胎养同理
  const t: Record<string, number> = { 帝: 100, 临: 86, 冠: 70, 长: 62, 养: 55, 胎: 48, 沐: 42, 衰: 38, 病: 28, 墓: 18, 死: 12, 绝: 5 };
  return t[s] ?? 50;
}
