                if (SHENG[yongWx] === tiWx) return `【用生体·大吉】用${yongWx}生体${tiWx}，这件事主动来帮我、送钱来、贵人从天降。坐等即可，不用行动。`;
                if (SHENG[tiWx] === yongWx) return `【体生用·小凶·耗】体${tiWx}生用${yongWx}，我要付出精力/时间/钱，才能推进这件事，泄气，费力不讨好，回报少。`;
                if (KEI[tiWx] === yongWx) return `【体克用·小吉·可成】体${tiWx}克用${yongWx}，我能掌控这件事，去做就能成，但要付出努力，能拿到结果。`;
                if (KEI[yongWx] === tiWx) return `【用克体·大凶·别做】用${yongWx}克体${tiWx}，这件事主动来坑我、破财、受伤、失败。千万不要去做！等时机再看。`;
