  '火贪格·铃贪格': { level: '上', plain: '【火铃+贪狼】=暴发户格局，35岁左右有一次横财机会(拆迁/股权/彩票/创业套现)，金额是普通人10年收入以上。', match: '贪狼与火星/铃星同宫或对照' },
