                const minorXiong = p.stars.filter((s: any) => ['擎羊', '陀罗', '火星', '铃星', '地空', '地劫'].includes(s.name)).length;
                const mutagen = p.stars.reduce((acc: number, s: any) => {
                  if (s.mutagen === '禄') return acc + 12;
                  if (s.mutagen === '权') return acc + 8;
                  if (s.mutagen === '科') return acc + 6;
                  if (s.mutagen === '忌') return acc - 15;
                  return acc;
                }, 0);
                score += major.length * 3 + minorJi * 5 - minorXiong * 6 + mutagen;
                const lv = score >= 80 ? '超级吉宫(90+分)' : score >= 65 ? '吉宫(70分)' : score >= 45 ? '中性宫(50分)' : score >= 30 ? '弱宫(35分)' : '凶宫(20分以下)';
                return { name: p.name, score, lv, major: major.map((s: any) => s.name).join('/') || '空宫', note: lv };
