              note: '【白话·怎么记】阳遁=顺排(1→2→3→4→5→6→7→8→9)，像时钟顺时针；阴遁=逆排(9→8→7→6→5→4→3→2→1)，像时钟逆时针。几局=值符(地盘六仪)落在哪一宫的洛书数。例：阳遁三局=戊在震三宫起步顺排。'
