            const SHENGXIAO = ['鼠','牛','虎','兔','龙','蛇','马','羊','猴','鸡','狗','猪'];
            const ZHI = ['子','丑','寅','卯','辰','巳','午','未','申','酉','戌','亥'];
            const yearZhi = ZHI[(year - 4) % 12];
            const yearSX = SHENGXIAO[(year - 4) % 12];
