            // 太岁方
            const TAI_SUI_FANG: Record<string, string> = { 子: '正北', 丑: '东北偏北', 寅: '东北偏东', 卯: '正东', 辰: '东南偏东', 巳: '东南偏南', 午: '正南', 未: '西南偏南', 申: '西南偏西', 酉: '正西', 戌: '西北偏西', 亥: '西北偏北' };
            // 九宫飞星五黄
