              note: '【四大吉神查法·甲己日举例】喜神在东北方(艮)·财神在正东方(震)·福神在东南方(巽)·天乙贵神在西南方(坤·丑)·东北方(艮·未)。【实操】去求财→面朝财神位坐；去约会→面朝喜神位坐；去考试→面朝贵神位坐；去探病→面朝福神位坐。'
