              value: '五黄→铜铃·六帝钱(金化土)｜二黑病符→铜葫芦(金化土+收病气)｜三煞→山海镇/八卦镜｜太岁→太岁符/红腰带/躲春｜岁破→龙龟(化冲)｜白虎开口→麒麟(压白虎)｜门冲→珠帘/玄关/植物｜尖角煞→铜貔貅化解｜穿堂煞→屏风/玄关挡住漏财｜桃花煞→桃木剑斩桃花',
