  '荧入太白(丙+庚)': '凶：火星入金星=贼必去。主：事情消退、对方突然变卦、人走了、物失了。【白话】之前谈好的合作容易黄，找的人可能已经离开。',
  '青龙逃走(乙+辛)': '凶：乙被辛克=龙跑了。主：破财、婚姻破裂、员工离职、合伙人撤资。【白话】要留的东西/人留不住，提前做好预案。',
  '白虎猖狂(辛+乙)': '凶：白虎猖狂=打斗伤灾。主：车祸、口角、血光、家宅不宁、小人当道。【白话】今日宜低调，勿开车斗气、勿与人吵架。',
  '螣蛇夭矫(癸+丁)': '凶：蛇虚惊怪。主：做噩梦、被骗、文书出错、信息乱、签错字。【白话】签合同前再读三遍、转账前再核对账号姓名。',
