  '小蛇化龙(壬+戊)': '小吉：壬小蛇+戊青龙=升级。主：小人物翻身、项目从0到1、小生意变大。【白话】不起眼的小事做好了，后续会变大惊喜。',
  '天网四张(癸+壬)': '大凶：癸壬水重=走投无路。主：事情办不成、被网罗住、出不去。【白话】今天不要签重要合同、不要做重大决策，先等一等。',
  '三奇得使': '大吉：三奇(乙丙丁)落到值使门宫=奇才被用。主：贵人出手、办事超顺、计划顺利执行。',
  '玉女守门': '大吉：丁(玉女)落到值使门=暗中成事。主：私事顺、女人帮忙、晚上的事成。',
  '五不遇时': '大凶：时干克日干(阳克阳/阴克阴)。主：时机完全不对，做什么都倒回去。【白话】此局宜等待、不宜主动办事，换个时辰再启动。',
