/** 日家奇门盘：以日为单位的择吉盘（休门三日一宫 + 太乙九星一日一宫 + 时辰黑黄道） */
export function QimenDayBoard({ chart }: { chart: QimenDayChart }) {
  const order = [4, 9, 2, 3, 5, 7, 8, 1, 6];
  const byGong = new Map(chart.cells.map(c => [c.gong, c]));
  const [popup, setPopup] = useState<PopupState | null>(null);

  const RI_STAR_NOTE: Record<string, string> = {
    太乙: '大吉，主求财万事通、贵人相助、出入皆吉',
    摄提: '大凶，主刑伤灾害、车马损折、诸事不宜',
    轩辕: '中平，主文书、车马、血光、婚喜',
    招摇: '凶，主口舌是非、官讼纠缠、小人暗算',
    天符: '中平，主官禄、公事、文书、贵人',
    青龙: '大吉，主觅利喜重重、求财顺、喜庆至',
    咸池: '凶，主桃花、色欲、破财、盗失、暗昧',
    太阴: '吉，主暗财丰、私事顺、女性贵人',
    天乙: '大吉，主贵人宜酒食、诸事皆顺、求谋得助',
  };
  const RI_GONG_ZHI: Record<number, string[]> = {
    1: ['子'], 8: ['丑', '寅'], 3: ['卯'], 4: ['辰', '巳'], 9: ['午'], 2: ['未', '申'], 7: ['酉'], 6: ['戌', '亥'], 5: [],
  };

  const explain = (c: (typeof chart.cells)[number]) => {
    const sections: PopupState['sections'] = [];
    sections.push({ label: '宫位·方位', value: `${c.name}（洛书${c.gong}宫）·${GONG_FANG[c.gong] ?? ''}` });
    sections.push({ label: '宫位地支', value: RI_GONG_ZHI[c.gong]?.join('·') ?? '' });
    if (c.star) sections.push({ label: `日家九星${c.gong === chart.taiYiGong ? '（太乙本日宫·重点）' : ''}：${c.star}`, value: c.star, note: RI_STAR_NOTE[c.star] ?? '' });
    if (c.gate) sections.push({ label: `八门：${c.gate}`, value: c.gate, note: GATE_NOTE[c.gate] ?? '' });
    if (c.marks.length) sections.push({ label: '本日吉标记', value: c.marks.join('、'), note: '吉门（休/生/开）+ 吉星（太乙/青龙/太阴/天乙）齐临=日家最佳方位。' });
    sections.push({ label: '择日用事', value: `本日${chart.dayPillar}日，${chart.jieqi}后${chart.yinYang}，喜神${chart.xiShen}`, note: '日家奇门=择吉体系：三吉门+吉星=当日可借之方位；时辰层面再结合十二黑黄道（黄道吉、黑道凶）。' });
    return { title: `日家奇门·${c.name}白话讲解`, sections };
  };

  return (
    <div>
      <div className="qm-grid qm-full">
        {order.map(g => {
          const c = byGong.get(g);
          if (!c) return <div key={g} className="qm-cell" style={{ background: 'transparent', borderStyle: 'dashed' }} />;
          const best = c.marks.some(m => m === '吉门' || m === '吉星');
          const zhi = RI_GONG_ZHI[g] ?? [];
          return (
            <div key={g} className={`qm-cell qm-cell-rich ${c.gong === chart.taiYiGong ? 'zhifu' : ''} ${best ? 'best' : ''}`} tabIndex={0}
              onClick={() => setPopup(explain(c))}
              aria-label={`${c.name} ${c.gate ?? '—'} ${c.star ?? '—'} ${c.marks.join('、')}`}>
              <div className="qm-row qm-top">
                <span className="qm-pos">{c.name.replace(/[一二三四五六七八九]$/, '')}</span>
                <span className="qm-god muted" style={{ fontSize: 11 }}>　</span>
                <span className="qm-yin-gan muted" style={{ fontSize: 11 }}>{zhi[1] || '　'}</span>
              </div>
              <div className="qm-row qm-mid-top">
                <span className="qm-zhi-left">{zhi[0] || ''}</span>
                <span className={`qm-star ${c.gong === chart.taiYiGong ? 'zhifu-red' : ''}`}
                  onClick={e => { e.stopPropagation(); if (c.star) setPopup({ title: `日家九星：${c.star}${c.gong === chart.taiYiGong ? '（太乙起点·本日重点）' : ''}`, sections: [{ label: '太乙九星', value: c.star, note: RI_STAR_NOTE[c.star] ?? '' }] }); }}
                  style={{ fontSize: 13 }}>{c.star ?? ''}</span>
                <span className="qm-digan-right muted" style={{ fontSize: 11 }}>　</span>
              </div>
              <div className="qm-row qm-center">
                <span className="qm-tiangan muted" style={{ fontSize: 13 }}>　</span>
                <span className="qm-gan-col"><span className="qm-tiangan-mid">·</span><span className="qm-digan-mid">·</span></span>
                <span className={`qm-gate ${c.gate && ['休门', '生门', '开门'].includes(c.gate) ? 'zhishi-red' : ''}`}
                  onClick={e => { e.stopPropagation(); if (c.gate) setPopup({ title: `八门：${c.gate}`, sections: [{ label: '日家门断', value: c.gate, note: GATE_NOTE[c.gate] ?? '' }] }); }}>
                  {c.gate ?? '（无门）'}
                </span>
              </div>
              <div className="qm-row qm-bottom">
                <span className="qm-zhi-full">{zhi.join('·') || '　'}</span>
                <span className="qm-xia-shen muted small">　</span>
                <span className={`qm-sheng ${best ? 'sheng-旺' : ''}`} style={{ fontSize: 12 }}>{c.marks.includes('吉门') ? '吉' : '　'}</span>
              </div>
              <div className="qm-marks-row">{c.marks.map(m => <span key={m} className={`qm-mark ${best ? 'mark-吉' : ''}`}>{m}</span>)}</div>
            </div>
          );
        })}
      </div>
      <div className="small muted" style={{ textAlign: 'center', marginTop: 6 }}>日家奇门·择日择方 · 点击宫位看白话讲解 · 红体=太乙或吉门</div>
      <InfoCard info={[
        { label: '起局', value: `${chart.dayPillar}日（日家以日为主，不看时家盘）` },
        { label: '阴/阳遁', value: `${chart.jieqi}后 ${chart.yinYang}` },
        { label: '休门', value: `${chart.cells.find(c => c.gong === chart.xiuMenGong)?.name ?? ''}（三日一宫）` },
        { label: '太乙', value: `${chart.cells.find(c => c.gong === chart.taiYiGong)?.name ?? ''}（一日一宫）` },
        { label: '时辰', value: `${chart.currentDao.shichen}：${chart.currentDao.shen}（${chart.currentDao.kind}）` },
        { label: '喜神', value: chart.xiShen },
        { label: '天乙贵人', value: chart.guiRen ?? '—' },
        { label: '格局', value: chart.patterns.join('；') || '无特殊格局' },
      ]} badges={[
        StepGuideCard({ art: 'rijia', onShowPopup: setPopup }),
        CaseLibraryCard({ art: 'rijia', onShowPopup: setPopup }),
      ]} />
      <ExplainerPopup popup={popup} onClose={() => setPopup(null)} />
    </div>
  );
}

