  'qimen.timing.chukong': '【白话·空亡应期】空亡=现在这个"十天"里轮不到它（比如甲子旬空戌亥，这十天戌亥位上没安排），等过了这十天=出旬=排到它了就真发生。或者它的"对冲位"到了也会被撞出来。',
  'qimen.timing.ge': '【白话·庚格应期】庚=一堵墙，事卡在墙上。撞墙的方法：(1)等庚落宫的"对冲日/月"(2)庚+X，X是年干=年内堵，X是日干=当日堵。',
  'qimen.timing.sanhe': '【白话·三合应期】三合局=三人组队：缺一个=等最后一个到了就开干；齐了=马上干。三个人=三个地支凑齐那天。',
  'qimen.timing.liuhe': '【白话·六合应期】六合=两个人绑定：一男一女、合同双方，等"另一方"那个地支到了就签字/结婚/成事。',
  'qimen.timing.luoshu': '【白话·洛书计期】民间最常用的"算天数"：乾6天/坎1天/艮8天…旺相=放大2倍（离9旺=18天），休囚=减半（离9休=3~4天）。',
  'qimen.timing.fanyin': '【白话·返吟应期】返吟=球撞墙弹回来：去了又回、成了又败、反反复复。应期在"撞"的那一刻=对冲日。',
  'qimen.timing.fuyin': '【白话·伏吟应期】伏吟=原地不动：车挂了P挡，怎么踩油门都不走。等①被冲(撞一下启动)②出空填实(排到它了)才能真走。',
  'liuyao.timing.liuchonggua': '【白话·六冲卦】六冲=六对地支对撞：事情动起来了但容易散——问好事=别高兴太早，问坏事=快点过去。一般应期在1~15天。',
  'liuyao.timing.liuhegua': '【白话·六合卦】六合=六对地支粘住：事情稳、慢、拖——问感情=如胶似漆，问合同=签字慢，问病=拖很久。一般应期在20天~3个月。',
  'liuyao.timing.youhun': '【白话·游魂卦】游魂=魂魄在外面飘荡：事情变数大、对方在犹豫、消息真假难辨——近则3天，远则3个月。',
  'liuyao.timing.guihun': '【白话·归魂卦】归魂=魂魄回家了：人归位、事定局、旧事再来一遍——快则当天，慢则30天。',
  'liuyao.timing.chukong': '【白话·旬空应期】用神"空亡"=暂时不在服务区：①等它值班那天回来=填实 ②等它对面那位值班时把它撞出来=冲实。出了这个10天=出旬，它就真上线了。',
  'liuyao.timing.dongdaihe': '【白话·动爻待合】动爻=发生的事，合=胶水粘住：动爻被六合粘住那天就落地（比如动爻在子，丑日粘住=成事）。',
  'liuyao.timing.dongdaichong': '【白话·动爻待值】旺相动爻=充满电的马达：等到它自己值班那天=事情马上发生（这一天就是地支与动爻相同的那天）。',
  'liuyao.timing.jinshen': '【白话·进神应期】同气进阶（寅→卯=木更强），力量在积累变大，一般3~9天就应，应时力量是正常的2倍。',
