  天德: '黄道吉神：天上最尊贵之吉神，百事皆宜，尤宜祈福还愿、修造动土。',
  玉堂: '黄道吉神：主"安床设帐"。宜安床、修造、宴请、读书，温润祥和。',
  司命: '黄道吉神：主"经营交易"。宜经商、签约、求嗣、开市，主谋事有成。',
