export function StepGuideCard({ art, onShowPopup, title }: { art: string; onShowPopup: (p: PopupState) => void; title?: string }) {
  const steps = STEP_GUIDE[art];
  if (!steps) return null;
  return React.createElement('span', {
    className: 'tag dai clickable',
    key: 'step-' + art,
    onClick: () => onShowPopup({
      title: title ?? `📘 ${({ qimen: '奇门遁甲', bazi: '八字命理', liuyao: '六爻金钱卦', meihua: '梅花易数', ziwei: '紫微斗数', liuren: '大六壬', xiaoliuren: '小六壬', jinkou: '金口诀', rijia: '日家奇门' } as Record<string,string>)[art] ?? art}·断卦六步走`,
      sections: steps.map(s => ({
        label: `📌 第${s.n}步：${s.t}`,
        value: s.t + (s.e ? '｜例：' + s.e : ''),
        note: s.p,
      })),
    }),
  }, '📘 断卦步骤·六步走');
}
export function CaseLibraryCard({ art, onShowPopup, subtitle }: { art: string; onShowPopup: (p: PopupState) => void; subtitle?: string }) {
  const cases = CASE_LIBRARY[art];
  if (!cases) return null;
  return React.createElement('span', {
    className: 'tag gold clickable',
    key: 'case-' + art,
    onClick: () => onShowPopup({
      title: `📚 ${({ qimen: '奇门遁甲', bazi: '八字', liuyao: '六爻', meihua: '梅花易数', ziwei: '紫微斗数', liuren: '大六壬', xiaoliuren: '小六壬', jinkou: '金口诀', rijia: '日家奇门择吉' } as Record<string,string>)[art] ?? art}·内置${cases.length}个真实案例（白话复盘）`,
      sections: cases.map((c, i) => ({
        label: `【案例${i + 1}】${c.t}`,
        value: c.q,
        note: '【师断】' + c.r + '\n\n【要点总结】' + c.l,
      })),
    }),
  }, `📚 案例库·${cases.length}例` + (subtitle ?? ''));
}

