/** 流程：按问事类别展示"八术各看什么"速查（向导 Step3 用，数据来自跨系统引擎表） */
const CAT_TO_TOPIC: Record<string, string> = {
  求财: '①', 财运: '①', 事业: '②', 工作: '②', 学业: '⑦', 考试: '⑦', 健康: '④', 疾病: '④',
  官非: '⑧', 诉讼: '⑧', 失物: '⑤', 出行: '⑥', 择日: '⑨', 家宅: '⑩', 生育: '⑪',
  合作: '⑫', 合伙: '⑫', 决策: '⑬', 感情: '③', 婚姻: '③',
};
function matchYongshen(category: string) {
  const prefix = CAT_TO_TOPIC[category] ?? '';
  if (prefix) return CROSS_SYSTEM_YONGSHEN.find(y => y.topic.startsWith(prefix)) ?? null;
  // 其他类兜底：按关键词模糊找
  return CROSS_SYSTEM_YONGSHEN.find(y => y.topic.includes(category)) ?? CROSS_SYSTEM_YONGSHEN[0] ?? null;
}
export function CategoryYongshenNote({ category, onShow }: { category: string; onShow: (p: PopupState) => void }) {
  const [open, setOpen] = useState(false);
  const y = useMemo(() => matchYongshen(category), [category]);
  if (!y) return null;
  const rows: Array<[string, string]> = [
    ['八字', y.bazi], ['六爻', y.liuyao], ['奇门', y.qimen], ['紫微', y.ziwei],
    ['大六壬', y.liuren], ['梅花', y.meihua], ['小六壬', y.xiaoliuren], ['金口诀', y.jinkou],
  ];
  return (
    <div style={{ marginTop: 12, padding: '8px 10px', border: '1px dashed var(--dai)', borderRadius: 10, background: 'var(--soft-a)' }}>
      <div className="row" style={{ justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '4px 12px' }}>
        <b className="small">🔍 此项问事 · 八术各看什么（{y.topic}）</b>
        <button className="btn sm ghost" onClick={() => setOpen(v => !v)}>{open ? '收起' : '展开速查'}</button>
      </div>
      {open && (
        <div style={{ marginTop: 8 }}>
          {rows.map(([name, txt]) => (
            <div key={name} className="small" style={{ marginBottom: 6, lineHeight: 1.6 }}>
              <span className="tag dai" style={{ marginRight: 6, fontSize: 11 }}>{name}</span>{txt}
            </div>
          ))}
          <button className="btn sm" style={{ marginTop: 6 }} onClick={() => onShow({
            title: `跨系统用神引擎 · ${y.topic}`,
            sections: rows.map(([name, txt]) => ({ label: `  · ${name}`, value: name, note: txt })),
          })}>🔍 点此把这条收进弹窗详细看</button>
        </div>
      )}
    </div>
  );
}

/** 精批白话卡：整盘综合断语（8 术+日家统一），点击展开全文；category 提供时附带"本题问事专断" */
export function JingPiCard({ art, chart, category }: { art: string; chart: unknown; category?: string }) {
  const [open, setOpen] = useState(false);
  const [pop, setPop] = useState<PopupState | null>(null);
  // 本题问事专断（按类别从跨系统引擎表取该术断语）
  const catNote = (() => {
    if (!category) return null;
    const y = matchYongshen(category);
    if (!y) return null;
    const artKey = ({ bazi: 'bazi', liuyao: 'liuyao', meihua: 'meihua', ziwei: 'ziwei', qimen: 'qimen', liuren: 'liuren', xiaoliuren: 'xiaoliuren', jinkou: 'jinkou', rijia: 'qimen' } as Record<string, keyof typeof y>)[art];
    const txt = artKey ? y[artKey] as string : null;
    return { topic: y.topic, txt, all: y };
  })();
  let data: { headline: string; segs: Array<{ title: string; body: string }>; tips: string[] } | null = null;
  let errMsg: string | null = null;
  try {
    const r = jingPiFor(art, chart as never);
    data = { headline: r.headline, segs: r.segs, tips: r.tips };
  } catch (e) {
    errMsg = (e as Error)?.message ?? String(e);
    data = null;
  }
  if (errMsg) {
    return (
      <div className="card" style={{ marginTop: 10 }}>
        <div className="row" style={{ justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '4px 12px' }}>
          <h3 className="card-title" style={{ margin: 0 }}>✨ 精批白话详解</h3>
          <button className="btn sm" onClick={() => setOpen(v => !v)}>{open ? '收起' : '详情'}</button>
        </div>
        {open && <div className="notice warn" style={{ marginTop: 8 }}>本盘暂无法自动生成精批（数据异常：{errMsg.slice(0, 60)}）。请看盘面逐格白话讲解。</div>}
      </div>
    );
  }
  if (!data || !data.segs.length) return null;
  const label = ({ qimen: '奇门遁甲', bazi: '八字', liuyao: '六爻', meihua: '梅花易数', ziwei: '紫微斗数', liuren: '大六壬', xiaoliuren: '小六壬', jinkou: '金口诀', rijia: '日家奇门' } as Record<string, string>)[art] ?? art;
  return (
    <div className="card" style={{ marginTop: 10 }}>
      <div className="row" style={{ justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '4px 12px' }}>
        <h3 className="card-title" style={{ margin: 0 }}>✨ 精批白话详解（{label}）</h3>
        <button className="btn sm" onClick={() => setOpen(v => !v)}>{open ? '收起' : '展开'}</button>
      </div>
      {open && (
        <div style={{ marginTop: 8 }}>
          <div className="notice info" style={{ fontSize: 14 }}>{data.headline}</div>
          {catNote && (
            <div style={{ marginTop: 8, padding: 8, border: '1px dashed var(--dai)', borderRadius: 8, background: 'var(--soft-a)' }}>
              <div className="row" style={{ justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '4px 12px' }}>
                <b className="small">🎯 本题问事 · 专断（{catNote.topic}）</b>
                <button className="btn sm ghost" style={{ fontSize: 11 }} onClick={() => setPop({
                  title: `八术各看什么 · ${catNote.topic}`,
                  sections: [['八字', catNote.all.bazi], ['六爻', catNote.all.liuyao], ['奇门', catNote.all.qimen], ['紫微', catNote.all.ziwei], ['大六壬', catNote.all.liuren], ['梅花', catNote.all.meihua], ['小六壬', catNote.all.xiaoliuren], ['金口诀', catNote.all.jinkou]].map(([n, t]) => ({ label: `  · ${n}`, value: String(n), note: String(t) })),
                })}>看其它七术 →</button>
              </div>
              {catNote.txt && <div className="small" style={{ marginTop: 5, lineHeight: 1.7 }}><span className="tag dai" style={{ marginRight: 6, fontSize: 11 }}>{({ bazi: '八字', liuyao: '六爻', meihua: '梅花易数', ziwei: '紫微斗数', qimen: '奇门遁甲', liuren: '大六壬', xiaoliuren: '小六壬', jinkou: '金口诀', rijia: '日家奇门' } as Record<string, string>)[art] ?? art}</span>{catNote.txt}</div>}
            </div>
          )}
          {data.segs.map(s => (
            <div key={s.title} style={{ marginTop: 8, padding: 8, background: 'var(--paper-2, rgba(47,72,88,.05))', borderRadius: 8 }}>
              <b className="small">{s.title}</b>
              <div className="small" style={{ marginTop: 3, lineHeight: 1.7 }}>{s.body}</div>
            </div>
          ))}
          {data.tips.length > 0 && (
            <div className="row wrap" style={{ marginTop: 8, gap: 6 }}>
              {data.tips.map(t => <span key={t} className="tag gold clickable" onClick={() => setPop({ title: '开运/心法', sections: [{ label: '心法', value: t, note: '传统文化参考，不构成确定性断言。' }] })}>{t}</span>)}
            </div>
          )}
        </div>
      )}
      <ExplainerPopup popup={pop} onClose={() => setPop(null)} />
    </div>
  );
}

export function BoardRenderer({ spec, chart, category }: { spec: BoardSpec; chart: unknown; category?: string }) {
  return (
    <div className="card">
      <h3 className="card-title">{spec.title}</h3>
      {(() => {
        const c = chart as never;
        switch (spec.art) {
          case 'bazi': return <BaziBoard chart={c as BaziChart} />;
          case 'liuyao': return <LiuyaoBoard chart={c as LiuyaoChart} />;
          case 'meihua': return <MeihuaBoard chart={c as MeihuaChart} />;
          case 'ziwei': return <ZiweiBoard chart={c as ZiweiChart} />;
          case 'qimen': return (c as { timeType?: string }).timeType === 'ri'
            ? <QimenDayBoard chart={c as QimenDayChart} />
            : <QimenBoard chart={c as QimenChart} />;
          case 'liuren': return <LiurenBoard chart={c as LiurenChart} />;
          case 'xiaoliuren': return <XiaoliurenBoard chart={c as XiaoliurenChart} />;
          case 'jinkou': return <JinkouBoard chart={c as JinkouChart} />;
          default: return <div className="muted">{ART_NAMES[spec.art]}盘面待渲染</div>;
        }
      })()}
      <JingPiCard art={spec.art} chart={chart} category={category ?? (spec.title.includes('日家') ? '择日' : undefined)} />
    </div>
  );
}
